import numpy as np, pandas as pd
from scipy.optimize import least_squares
d=df.copy()
S=d.S.values; I=d.I.values; v=d.v.values
def mk(kind):
    def f(p,S,I):
        Vm,Km,Ki=p[0],p[1],p[2]
        if kind=='comp': return Vm*S/(Km*(1+I/Ki)+S)
        if kind=='nonc': return Vm*S/((Km+S)*(1+I/Ki))
        if kind=='unc': return Vm*S/(Km+S*(1+I/Ki))
        if kind=='mixed':
            a=p[3]; return Vm*S/(Km*(1+I/Ki)+S*(1+I/(a*Ki)))
    return f
res={}
for kind,np_ in [('comp',3),('nonc',3),('unc',3),('mixed',4)]:
    f=mk(kind); best=None
    for Vm0 in [8,10,15]:
        for Km0 in [1,3,8]:
            for Ki0 in [0.5,2,10]:
                p0=[Vm0,Km0,Ki0]+([1.0] if np_==4 else [])
                try:
                    r=least_squares(lambda p: f(p,S,I)-v, p0, bounds=([0.01]*np_,[1e3]*np_))
                except Exception as e: continue
                if best is None or r.cost<best.cost: best=r
    n=len(v); rss=2*best.cost
    bic=n*np.log(rss/n)+np_*np.log(n)
    res[kind]=best
    print(kind, np.round(best.x,4), 'RSS',round(rss,4),'BIC',round(bic,2))
    print(' resid by I:', {i: np.round(np.mean((f(best.x,S,I)-v)[I==i]),3) for i in [0,1,3]})

